55	static libzippp_uint16 convertCompressionToLibzip(CompressionMethod comp) {
56	    switch(comp) {
57	        case CompressionMethod::STORE:
58	            return ZIP_CM_STORE;
59	#ifdef ZIP_CM_BZIP2
60	        case CompressionMethod::BZIP2:
61	            return ZIP_CM_BZIP2;
62	#endif
63	        case CompressionMethod::DEFLATE:
64	            return ZIP_CM_DEFLATE;
65	#ifdef ZIP_CM_XZ
66	        case CompressionMethod::XZ:
67	            return ZIP_CM_XZ;
68	#endif
69	#ifdef ZIP_CM_ZSTD
70	        case CompressionMethod::ZSTD:
71	            return ZIP_CM_ZSTD;
72	#endif
73	        default:
74	            return ZIP_CM_DEFAULT;
75	    }
76	}
