78	static CompressionMethod convertCompressionFromLibzip(libzippp_uint16 comp) {
79	    switch(comp) {
80	      case ZIP_CM_STORE:
81	          return CompressionMethod::STORE;
82	#ifdef ZIP_CM_BZIP2
83	      case ZIP_CM_BZIP2:
84	          return CompressionMethod::BZIP2;
85	#endif
86	      case ZIP_CM_DEFLATE:
87	          return CompressionMethod::DEFLATE;
88	#ifdef ZIP_CM_XZ
89	      case ZIP_CM_XZ:
90	          return CompressionMethod::XZ;
91	#endif
92	#ifdef ZIP_CM_ZSTD
93	      case ZIP_CM_ZSTD:
94	          return CompressionMethod::ZSTD;
95	#endif
96	      default:
97	          return CompressionMethod::DEFAULT;
98	    }
99	}
