102	    static void callErrorHandlingCallbackFunc(const std::string& message, int zip_error_code, int system_error_code, ErrorHandlerCallback* callback) {
103	        zip_error_t error;
104	        zip_error_init(&error);
105	        zip_error_set(&error, zip_error_code, system_error_code);
106	        std::string strerror(zip_error_strerror(&error));
107	        (*callback)(message, strerror, zip_error_code, system_error_code);
108	        zip_error_fini(&error);
109	    }
110	
111	    static void callErrorHandlingCallback(zip* zipHandle, const std::string& msg, ErrorHandlerCallback* callback) {
112	        if (zipHandle!=nullptr) {
113	            zip_error_t* error_code = zip_get_error(zipHandle);
114	            callErrorHandlingCallbackFunc(msg, error_code->zip_err, error_code->sys_err, callback);
115	        } else {
116	            callErrorHandlingCallbackFunc("", -1, -1, callback);
117	        }
118	    }
119	
120	    static void callErrorHandlingCallback(zip_error_t* error, const std::string& msg, ErrorHandlerCallback* callback) {
121	        int error_code_zip, error_code_system;
122	        error_code_zip = zip_error_code_zip(error);
123	        error_code_system = zip_error_code_system(error);
124	        callErrorHandlingCallbackFunc(msg, error_code_zip, error_code_system, callback);
125	    }
126	}
