259	bool ZipArchive::openBuffer(void** data, libzippp_uint32 size, OpenMode om, bool checkConsistency) {
260	    zip_error_t error;
261	    zip_error_init(&error);
262	
263	    /* create source from buffer */
264	    zip_source* localZipSource = zip_source_buffer_create(*data, size, 0, &error);
265	    if (localZipSource == nullptr) {
266	        Helper::callErrorHandlingCallback(&error, "can't create zip source: %s\n", errorHandlingCallback);
267	        zip_error_fini(&error);
268	        return false;
269	    }
270	
271	    bool open = openSource(localZipSource, om, checkConsistency);
272	    if (open) {
273	        if (om==Write || om==New) {
274	            bufferData = data;
275	            bufferLength = size;
276	
277	            //prevents libzip to delete the source when closing the ZipArchive
278	            zip_source_keep(localZipSource);
279	        }
280	    } else {
281	        zip_source_free(localZipSource);
282	        localZipSource = nullptr;
283	    }
284	    return open;
285	}
