287	bool ZipArchive::openSource(zip_source* source, OpenMode om, bool checkConsistency) {
288	    int zipFlag = 0;
289	    if (om == ReadOnly) { zipFlag = 0; }
290	    else if (om == Write) { zipFlag = ZIP_CREATE; }
291	    else if (om == New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
292	    else { return false; }
293	    if (checkConsistency) {
294	        zipFlag = zipFlag | ZIP_CHECKCONS;
295	    }
296	
297	    zip_error_t error;
298	    zip_error_init(&error);
299	
300	    /* open zip archive from source */
301	    zipHandle = zip_open_from_source(source, zipFlag, &error);
302	    if (zipHandle == nullptr) {
303	        Helper::callErrorHandlingCallback(&error, "can't open zip from source: %s\n", errorHandlingCallback);
304	        zip_error_fini(&error);
305	        return false;
306	    }
307	    zip_error_fini(&error);
308	
309	    zipSource = source;
310	
311	#ifdef LIBZIPPP_WITH_ENCRYPTION
312	    if (isEncrypted()) {
313	        int result = zip_set_default_password(zipHandle, password.c_str());
314	        if (result != 0) {
315	            close();
316	            return false;
317	        }
318	    }
319	#endif
320	
321	    mode = om;
322	    return true;
323	}
