325	bool ZipArchive::open(OpenMode om, bool checkConsistency) {
326	    if (isOpen()) { return om==mode; }
327	
328	    int zipFlag = 0;
329	    if (om==ReadOnly) { zipFlag = 0; }
330	    else if (om==Write) { zipFlag = ZIP_CREATE; }
331	    else if (om==New) { zipFlag = ZIP_CREATE | ZIP_TRUNCATE; }
332	    else { return false; }
333	
334	    if (checkConsistency) {
335	        zipFlag = zipFlag | ZIP_CHECKCONS;
336	    }
337	
338	    int errorFlag = 0;
339	    zipHandle = zip_open(path.c_str(), zipFlag, &errorFlag);
340	
341	    //error during opening of the file
342	    if (errorFlag!=ZIP_ER_OK) {
343	        zip_error_t error;
344	        zip_error_init_with_code(&error, errorFlag);
345	        Helper::callErrorHandlingCallback(&error, "unable to open archive: %s\n", errorHandlingCallback);
346	        zip_error_fini(&error);
347	
348	        zipHandle = nullptr;
349	        return false;
350	    }
351	
352	    if (zipHandle!=nullptr) {
353	#ifdef LIBZIPPP_WITH_ENCRYPTION
354	        if (isEncrypted()) {
355	            int result = zip_set_default_password(zipHandle, password.c_str());
356	            if (result!=0) {
357	                close();
358	                return false;
359	            }
360	        }
361	#endif
362	
363	        mode = om;
364	        return true;
365	    }
366	
367	    return false;
368	}
