370	void progress_callback(zip* /*archive*/, double progression, void* ud) {
371	    ZipArchive* za = static_cast<ZipArchive*>(ud);
372	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
373	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
374	        ZipProgressListener* listener = *it;
375	        listener->progression(progression);
376	    }
377	}
378	
379	int progress_cancel_callback(zip* /*archive*/, void* ud) {
380	    ZipArchive* za = static_cast<ZipArchive*>(ud);
381	    vector<ZipProgressListener*> listeners = za->getProgressListeners();
382	    for(vector<ZipProgressListener*>::const_iterator it=listeners.begin() ; it!=listeners.end() ; ++it) {
383	        ZipProgressListener* listener = *it;
384	        if (listener->cancel())
385	          return 1;
386	    }
387	    return 0;
388	}
