390	int ZipArchive::close(void) {
391	    if (isOpen()) {
392	
393	        //do not handle zipSource at all because it will be deleted by libzip
394	        //directly when not necessary anymore
395	
396	        if (!listeners.empty()) {
397	            zip_register_progress_callback_with_state(zipHandle, progressPrecision, progress_callback, nullptr, this);
398	            zip_register_cancel_callback_with_state(zipHandle, progress_cancel_callback, nullptr, this);
399	        }
400	
401	        //avoid to reset the progress when unzipping
402	        if (mode != ReadOnly) {
403	            progress_callback(zipHandle, 0, this); //enforce the first progression call to be zero
404	        }
405	
406	        int result = zip_close(zipHandle);
407	        if (result!=0) {
408	            Helper::callErrorHandlingCallback(zipHandle, "unable to close archive: %s\n", errorHandlingCallback);
409	            return LIBZIPPP_ERROR_HANDLE_FAILURE;
410	        }
411	
412	        zipHandle = nullptr;
413	        progress_callback(zipHandle, 1, this); //enforce the last progression call to be one
414	
415	        //push back the changes in the buffer
416	        int res_code = LIBZIPPP_OK;
417	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
418	            int srcOpen = zip_source_open(zipSource);
419	            if (srcOpen==0) {
420	                //IMPORTANT: the rewritten archive is read back into a *freshly allocated*
421	                //buffer. We must never read into nor realloc *bufferData here: that memory
422	                //is the storage backing the libzip source we are currently reading from.
423	                //Reusing it aliases the source and, depending on the libzip version (i.e.
424	                //whether it takes ownership of the buffer when writing), it makes
425	                //zip_source_free() release a buffer that realloc() already moved/freed,
426	                //which results in a double-free (see double_free_report / fromWritableBuffer).
427	                zip_int64_t increment = 1024;
428	                zip_int64_t capacity = bufferLength>0 ? static_cast<zip_int64_t>(bufferLength) : increment;
429	                char* outBuffer = static_cast<char*>(malloc(capacity * sizeof(char)));
430	                char* tempBuffer = outBuffer;
431	                zip_int64_t tempBufferSize = capacity;
432	                zip_int64_t totalRead = 0;
433	                zip_int64_t read = (outBuffer==nullptr) ? -1 : zip_source_read(zipSource, tempBuffer, tempBufferSize);
434	                while(read>0) {
435	                    totalRead += read;
436	                    if (totalRead>=capacity) {
437	                        zip_int64_t newCapacity = capacity + increment;
438	                        char* grownBuffer = static_cast<char*>(realloc(outBuffer, newCapacity * sizeof(char)));
439	                        if (grownBuffer==nullptr) {
440	                            Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: unable to extend buffer\n", errorHandlingCallback);
441	                            ::free(outBuffer);
442	                            outBuffer = nullptr;
443	                            read = -1;
444	                            break;
445	                        }
446	                        outBuffer = grownBuffer;
447	                        capacity = newCapacity;
448	                    }
449	                    tempBuffer = outBuffer+totalRead;
450	                    tempBufferSize = capacity-totalRead;
451	                    read = zip_source_read(zipSource, tempBuffer, tempBufferSize);
452	                }
453	
454	                zip_source_close(zipSource);
455	
456	                if (outBuffer!=nullptr && read>=0) {
457	                    //freeing zipSource first guarantees libzip has released whatever it owns
458	                    //before we touch *bufferData. With freep=0 (see openBuffer) libzip never
459	                    //frees *bufferData itself, so reclaiming it here is safe and leak-free.
460	                    zip_source_free(zipSource);
461	                    zipSource = nullptr;
462	
463	                    ::free(*bufferData);
464	                    *bufferData = outBuffer;
465	                    bufferLength = totalRead;
466	                } else {
467	                    Helper::callErrorHandlingCallback(zipHandle, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
468	                    res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
469	                    if (outBuffer!=nullptr) { ::free(outBuffer); }
470	                    zip_source_free(zipSource);
471	                    zipSource = nullptr;
472	                }
473	            } else {
474	                Helper::callErrorHandlingCallback((zip*)nullptr, "can't read back from source: changes were not pushed in the buffer\n", errorHandlingCallback);
475	                res_code = LIBZIPPP_ERROR_HANDLE_FAILURE;
476	
477	                zip_source_free(zipSource);
478	                zipSource = nullptr;
479	            }
480	        }
481	
482	        mode = NotOpen;
483	        return res_code;
484	    }
485	
486	    return LIBZIPPP_OK;
487	}
