489	void ZipArchive::discard(void) {
490	    if (isOpen()) {
491	        zip_discard(zipHandle);
492	        zipHandle = nullptr;
493	
494	        if (bufferData!=nullptr && (mode==New || mode==Write)) {
495	            zip_source_free(zipSource);
496	            zipSource = nullptr;
497	        }
498	
499	        mode = NotOpen;
500	    }
501	}
