509	string ZipArchive::getComment(State state) const {
510	    if (!isOpen()) { return string(); }
511	
512	    int flag = 0;
513	    if (state==Original) { flag = flag | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
514	    else { flag = flag | ZIP_FL_ENC_GUESS; }
515	
516	    int length = 0;
517	    const char* comment = zip_get_archive_comment(zipHandle, &length, flag);
518	    if (comment==nullptr) { return string(); }
519	    return string(comment, length);
