532	bool ZipArchive::setEntryCompressionConfig(ZipEntry& entry, CompressionMethod comp, libzippp_uint32 level) const {
533	    if (!isOpen()) { return false; }
534	    if (entry.zipFile!=this) { return false; }
535	    if (mode==ReadOnly) { return false; }
536	    const libzippp_uint16 comp_libzip = convertCompressionToLibzip(comp);
537	
538	    bool success = zip_set_file_compression(zipHandle, entry.index, comp_libzip, level)==0;
539	    if (success) {
540	        entry.compressionMethod = comp_libzip;
541	        entry.compressionLevel = level;
542	    }
543	    return success;
