553	ZipEntry ZipArchive::createEntry(struct zip_stat* stat) const {
554	    string name(stat->name);
555	    libzippp_uint64 index = stat->index;
556	    libzippp_uint64 size = stat->size;
557	    libzippp_uint16 compMethod;
558	    if (useArchiveCompressionMethod) {
559	        compMethod = this->compressionMethod;
560	    } else {
561	        compMethod = stat->comp_method;
562	    }
563	    libzippp_uint16 encMethod = stat->encryption_method;
564	    libzippp_uint64 sizeComp = stat->comp_size;
565	    int crc = stat->crc;
566	    time_t time = stat->mtime;
567	
568	    return ZipEntry(this, name, index, time, compMethod, compressionLevel, encMethod, size, sizeComp, crc);
569	}
