571	vector<ZipEntry> ZipArchive::getEntries(State state) const {
572	    if (!isOpen()) { return vector<ZipEntry>(); }
573	
574	    struct zip_stat stat;
575	    zip_stat_init(&stat);
576	
577	    vector<ZipEntry> entries;
578	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
579	    libzippp_int64 nbEntries = getNbEntries(state);
580	    for(libzippp_int64 i=0 ; i<nbEntries ; ++i) {
581	        int result = zip_stat_index(zipHandle, i, flag, &stat);
582	        if (result==0) {
583	            ZipEntry entry = createEntry(&stat);
584	            entries.push_back(entry);
585	        } else {
586	            //TODO handle read error => crash ?
587	        }
588	    }
589	    return entries;
590	}
