592	bool ZipArchive::hasEntry(const string& name, bool excludeDirectories, bool caseSensitive, State state) const {
593	    if (!isOpen()) { return false; }
594	
595	    int flags = 0;
596	    if (excludeDirectories) { flags = flags | ZIP_FL_NODIR; }
597	    if (!caseSensitive) { flags = flags | ZIP_FL_NOCASE; }
598	    if (state==Original) { flags = flags | LIBZIPPP_ORIGINAL_STATE_FLAGS; }
599	    else { flags = flags | ZIP_FL_ENC_GUESS; }
600	
601	    libzippp_int64 index = zip_name_locate(zipHandle, name.c_str(), flags);
602	    return index>=0;
603	}
