660	void* ZipArchive::readEntry(const ZipEntry& zipEntry, bool asText, State state, libzippp_uint64 size) const {
661	    if (!isOpen()) { return nullptr; }
662	    if (zipEntry.zipFile!=this) { return nullptr; }
663	
664	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
665	    struct zip_file* zipFile = zip_fopen_index(zipHandle, zipEntry.getIndex(), flag);
666	    if (zipFile) {
667	        libzippp_uint64 maxSize = zipEntry.getSize();
668	        libzippp_uint64 uisize = size==0 || size>maxSize ? maxSize : size;
669	
670	        char* data = NEW_CHAR_ARRAY(uisize+(asText ? 1 : 0))
671	        if (!data) { //allocation error
672	            zip_fclose(zipFile);
673	            return nullptr;
674	        }
675	
676	        libzippp_int64 result = zip_fread(zipFile, data, uisize);
677	        zip_fclose(zipFile);
678	
679	        //avoid buffer copy
680	        if (asText) { data[uisize] = '\0'; }
681	
682	        libzippp_int64 isize = (libzippp_int64)uisize;
683	        if (result==isize) {
684	            return data;
685	        } else { //unexpected number of bytes read => crash ?
686	            delete[] data;
687	        }
688	    } else {
689	        //unable to read the entry => crash ?
690	    }
691	
692	    return nullptr;
693	}
