701	int ZipArchive::deleteEntry(const ZipEntry& entry) const {
702	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
703	    if (entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
704	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //deletion not allowed
705	
706	    if (entry.isFile()) {
707	        int result = zip_delete(zipHandle, entry.getIndex());
708	        if (result==0) { return 1; }
709	        return LIBZIPPP_ERROR_UNKNOWN; //unable to delete the entry
710	    } else {
711	        int counter = 0;
712	        vector<ZipEntry> allEntries = getEntries();
713	        vector<ZipEntry>::const_iterator eit;
714	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
715	            ZipEntry ze = *eit;
716	            string::size_type startPosition = ze.getName().find(entry.getName());
717	            if (startPosition==0) {
718	                int result = zip_delete(zipHandle, ze.getIndex());
719	                if (result==0) { ++counter; }
720	                else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to remove the current entry
721	            }
722	        }
723	        return counter;
724	    }
725	}
