733	int ZipArchive::renameEntry(const ZipEntry& entry, const string& newName) const {
734	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
735	    if (entry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
736	    if (mode==ReadOnly) { return LIBZIPPP_ERROR_NOT_ALLOWED; } //renaming not allowed
737	    if (newName.length()==0) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
738	    if (newName==entry.getName()) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
739	
740	    if (entry.isFile()) {
741	        if (LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //invalid new name
742	
743	        string::size_type lastSlash = newName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
744	        if (lastSlash!=1) {
745	            bool dadded = addEntry(newName.substr(0, lastSlash+1));
746	            if (!dadded) { return LIBZIPPP_ERROR_UNKNOWN; } //the hierarchy hasn't been created
747	        }
748	
749	        int result = zip_file_rename(zipHandle, entry.getIndex(), newName.c_str(), ZIP_FL_ENC_GUESS);
750	        if (result==0) { return 1; }
751	        return LIBZIPPP_ERROR_UNKNOWN; //renaming was not possible (entry already exists ?)
752	    } else {
753	        if (!LIBZIPPP_ENTRY_IS_DIRECTORY(newName)) { return LIBZIPPP_ERROR_INVALID_PARAMETER; } //invalid new name
754	
755	      string::size_type parentSlash = newName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR, newName.length()-2);
756	        if (parentSlash!=string::npos) { //updates the dir hierarchy
757	            string parent = newName.substr(0, parentSlash+1);
758	            bool dadded = addEntry(parent);
759	            if (!dadded) { return LIBZIPPP_ERROR_UNKNOWN; }
760	        }
761	
762	        int counter = 0;
763	        string originalName = entry.getName();
764	        vector<ZipEntry> allEntries = getEntries();
765	        vector<ZipEntry>::const_iterator eit;
766	        for(eit=allEntries.begin() ; eit!=allEntries.end() ; ++eit) {
767	            ZipEntry ze = *eit;
768	            string currentName = ze.getName();
769	
770	            string::size_type startPosition = currentName.find(originalName);
771	            if (startPosition==0) {
772	                if (currentName == originalName) {
773	                    int result = zip_file_rename(zipHandle, entry.getIndex(), newName.c_str(), ZIP_FL_ENC_GUESS);
774	                    if (result==0) { ++counter; }
775	                    else { return LIBZIPPP_ERROR_UNKNOWN;  } //unable to rename the folder
776	                } else  {
777	                    string targetName = currentName.replace(0, originalName.length(), newName);
778	                    int result = zip_file_rename(zipHandle, ze.getIndex(), targetName.c_str(), ZIP_FL_ENC_GUESS);
779	                    if (result==0) { ++counter; }
780	                    else { return LIBZIPPP_ERROR_UNKNOWN; } //unable to rename a sub-entry
781	                }
782	            } else {
783	                //file not affected by the renaming
784	            }
785	        }
786	
787	        /*
788	         * Special case for moving a directory a/x to a/x/y to avoid to lose
789	         * the a/x path in the archive.
790	         */
791	        bool newNameIsInsideCurrent = (newName.find(entry.getName())==0);
792	        if (newNameIsInsideCurrent) {
793	            bool dadded = addEntry(newName);
794	            if (!dadded) { return LIBZIPPP_ERROR_UNKNOWN; }
795	        }
796	
797	        return counter;
798	    }
799	}
