807	bool ZipArchive::addFile(const string& entryName, const string& file) const {
808	    if (!isOpen()) { return false; }
809	    if (mode==ReadOnly) { return false; } //adding not allowed
810	    if (LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
811	
812	    string::size_type lastSlash = entryName.rfind(LIBZIPPP_ENTRY_PATH_SEPARATOR);
813	    if (lastSlash!=string::npos) { //creates the needed parent directories
814	        string dirEntry = entryName.substr(0, lastSlash+1);
815	        bool dadded = addEntry(dirEntry);
816	        if (!dadded) { return false; }
817	    }
818	
819	    const char* filepath = file.c_str();
820	    zip_source* source = zip_source_file(zipHandle, filepath, 0, -1);
821	    if (source!=nullptr) {
822	        libzippp_int64 result = zip_file_add(zipHandle, entryName.c_str(), source, ZIP_FL_OVERWRITE);
823	        if (result>=0) {
824	            zip_file_set_mtime(zipHandle, result, time(nullptr), 0);
825	            if (useArchiveCompressionMethod) {
826	              zip_set_file_compression(zipHandle, result, compressionMethod, 0);
827	            }
828	#ifdef LIBZIPPP_WITH_ENCRYPTION
829	            if (isEncrypted()) {
830	                if (zip_file_set_encryption(zipHandle,result,encryptionMethod,nullptr)!=0) { //unable to encrypt
831	                    zip_source_free(source);
832	                } else {
833	                    return true;
834	                }
835	            } else {
836	                return true;
837	            }
838	#else
839	            return true;
840	#endif
841	        } else {
842	            //unable to add the file
843	            zip_source_free(source);
844	        }
845	    } else {
846	        //unable to create the zip_source
847	    }
848	    return false;
849	}
