898	bool ZipArchive::addEntry(const string& entryName) const {
899	    if (!isOpen()) { return false; }
900	    if (mode==ReadOnly) { return false; } //adding not allowed
901	    if (!LIBZIPPP_ENTRY_IS_DIRECTORY(entryName)) { return false; }
902	
903	    string::size_type nextSlash = entryName.find(LIBZIPPP_ENTRY_PATH_SEPARATOR);
904	    while (nextSlash!=string::npos) {
905	        string pathToCreate = entryName.substr(0, nextSlash+1);
906	        if (!hasEntry(pathToCreate)) {
907	            libzippp_int64 result = zip_dir_add(zipHandle, pathToCreate.c_str(), ZIP_FL_ENC_GUESS);
