936	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::ostream& ofOutput, State state, libzippp_uint64 chunksize) const {
937	    if (!ofOutput) { return LIBZIPPP_ERROR_INVALID_PARAMETER; }
938	    std::function<bool(const void*,libzippp_uint64)> writeFunc = [&ofOutput](const void* data,libzippp_uint64 size){ ofOutput.write((char*)data, size); return bool(ofOutput); };
939	    return readEntry(zipEntry, writeFunc, state, chunksize);
940	}
941	
942	int ZipArchive::readEntry(const ZipEntry& zipEntry, std::function<bool(const void*,libzippp_uint64)> writeFunc, State state, libzippp_uint64 chunksize) const {
943	    if (!isOpen()) { return LIBZIPPP_ERROR_NOT_OPEN; }
944	    if (zipEntry.zipFile!=this) { return LIBZIPPP_ERROR_INVALID_ENTRY; }
945	
946	    int iRes = LIBZIPPP_OK;
947	    int flag = state==Original ? LIBZIPPP_ORIGINAL_STATE_FLAGS : ZIP_FL_ENC_GUESS;
948	    struct zip_file* zipFile = zip_fopen_index(zipHandle, zipEntry.getIndex(), flag);
949	    if (zipFile) {
950	        libzippp_uint64 maxSize = zipEntry.getSize();
951	        if (!chunksize) { chunksize = LIBZIPPP_DEFAULT_CHUNK_SIZE; } // use the default chunk size (512K) if not specified by the user
952	
953	        if (maxSize<chunksize) {
954	            char* data = NEW_CHAR_ARRAY(maxSize)
955	            if (data!=nullptr) {
956	                libzippp_int64 result = zip_fread(zipFile, data, maxSize);
957	                if (result>=0) {
958	                    if (result != static_cast<libzippp_int64>(maxSize)) {
959	                        iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
960	                    } else if (!writeFunc(data, maxSize)) {
961	                        iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
962	                    }
963	                } else {
964	                    iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
965	                }
966	                delete[] data;
967	            } else {
968	                iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
969	            }
970	        } else {
971	            libzippp_uint64 uWrittenBytes = 0;
972	            libzippp_int64 result = 0;
973	            char* data = NEW_CHAR_ARRAY(chunksize)
974	            if (data!=nullptr) {
975	                string::size_type nbChunks = maxSize/chunksize;
976	                for (libzippp_uint32 uiChunk=0 ; uiChunk<nbChunks ; ++uiChunk) {
977	                    result = zip_fread(zipFile, data, chunksize);
978	                    if (result>=0) {
979	                        if (result!=static_cast<libzippp_int64>(chunksize)) {
980	                            iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
981	                            break;
982	                        } else {
983	                            if (!writeFunc(data, chunksize)) {
984	                                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
985	                                break;
986	                            }
987	                            uWrittenBytes += result;
988	                        }
989	                    } else {
990	                        iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
991	                        break;
992	                    }
993	                }
994	                delete[] data;
995	            } else {
996	                iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
997	            }
998	
999	            libzippp_uint64 leftOver = maxSize%chunksize;
1000	            if (iRes==0 && leftOver>0) {
1001	                char* data = NEW_CHAR_ARRAY(leftOver);
1002	                if (data!=nullptr) {
1003	                    result = zip_fread(zipFile, data, leftOver);
1004	                    if (result>=0) {
1005	                        if (result!=static_cast<libzippp_int64>(leftOver)) {
1006	                            iRes = LIBZIPPP_ERROR_OWRITE_INDEX_FAILURE;
1007	                        } else {
1008	                            if (!writeFunc(data, leftOver)) {
1009	                                iRes = LIBZIPPP_ERROR_OWRITE_FAILURE;
1010	                            } else {
1011	                                uWrittenBytes += result;
1012	                                if (uWrittenBytes!=maxSize) {
1013	                                    iRes = LIBZIPPP_ERROR_UNKNOWN; // shouldn't occur but let's be careful
1014	                                }
1015	                            }
1016	                        }
1017	                    } else {
1018	                        iRes = LIBZIPPP_ERROR_FREAD_FAILURE;
1019	                    }
1020	                } else {
1021	                    iRes = LIBZIPPP_ERROR_MEMORY_ALLOCATION;
1022	                }
1023	                delete[] data;
1024	            }
1025	        }
1026	        zip_fclose(zipFile);
1027	    } else {
1028	       iRes = LIBZIPPP_ERROR_FOPEN_FAILURE;
1029	    }
1030	    return iRes;
1031	}
