    if (content==nullptr) { return basic_string<libzippp_uint8>(); } //happen if the ZipArchive has been closed

    libzippp_uint64 maxSize = getSize();
    basic_string<libzippp_uint8> str(content, (size==0 || size>maxSize ? maxSize : size));
    delete[] content;
    return str;
}

