987	        0x5f, 0x63, 0x6f, 0x6e, 0x74, 0x65, 0x6e, 0x74, 0x2e, 0x74, 0x78, 0x74,
988	        0x55, 0x54, 0x09, 0x00, 0x03, 0xa8, 0x39, 0x0f, 0x68, 0xa8, 0x39, 0x0f,
989	        0x68, 0x75, 0x78, 0x0b, 0x00, 0x01, 0x04, 0x00, 0x00, 0x00, 0x00, 0x04,
990	        0x00, 0x00, 0x00, 0x00, 0x41, 0x46, 0x4c, 0x2b, 0x2b, 0x20, 0x66, 0x75,
991	        0x7a, 0x7a, 0x20, 0x74, 0x65, 0x73, 0x74, 0x20, 0x73, 0x61, 0x6d, 0x70,
992	        0x6c, 0x65, 0x2e, 0x0a, 0x50, 0x4b, 0x01, 0x02, 0x1e, 0x03, 0x0a, 0x00,
993	        0x00, 0x00, 0x00, 0x00, 0x36, 0x42, 0x9c, 0x5a, 0xfa, 0x29, 0x42, 0xbc,
994	        0x18, 0x00, 0x00, 0x00, 0x18, 0x00, 0x00, 0x00, 0x12, 0x00, 0x18, 0x00,
995	        0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0xa4, 0x81, 0x00, 0x00,
996	        0x00, 0x00, 0x73, 0x61, 0x6d, 0x70, 0x6c, 0x65, 0x5f, 0x63, 0x6f, 0x6e,
997	        0x74, 0x65, 0x6e, 0x74, 0x2e, 0x74, 0x78, 0x74, 0x55, 0x54, 0x05, 0x00,
998	        0x03, 0xa8, 0x39, 0x0f, 0x68, 0x75, 0x78, 0x0b, 0x00, 0x01, 0x04, 0x00,
999	        0x00, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x00, 0x50, 0x4b, 0x05, 0x06,
1000	        0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x58, 0x00, 0x00, 0x00,
1001	        0x64, 0x00, 0x00, 0x00, 0x00, 0x00,
1002	    };
1003	    const libzippp_uint32 craftedSize = sizeof(craftedZip);
1004	
1005	    // --- exact reproduction of the reported harness: writable buffer (with headroom),
1006	    //     open in Write mode, perform one modification, then close. ---
1007	    {
1008	        libzippp_uint32 bufferSize = craftedSize + 4096;
1009	        void* buffer = calloc(bufferSize, sizeof(char)); //must be malloc/calloc for fromWritableBuffer
1010	        memcpy(buffer, craftedZip, craftedSize);
1011	
1012	        ZipArchive* z = ZipArchive::fromWritableBuffer(&buffer, bufferSize, ZipArchive::Write);
1013	        assert(z != nullptr);
1014	        z->addEntry("fuzz_entry/");
1015	        int rst = z->close(); //used to double-free here
1016	        assert(rst == LIBZIPPP_OK);
1017	
1018	        //the buffer must remain reopenable after the rewrite (no corruption of the pointer)
1019	        libzippp_uint32 newLength = (libzippp_uint32)z->getBufferLength();
1020	        ZipArchive::free(z);
1021	
1022	        ZipArchive* zr = ZipArchive::fromBuffer(buffer, newLength);
1023	        assert(zr != nullptr);
1024	        assert(zr->hasEntry("fuzz_entry/"));
1025	        ZipArchive::free(zr);
1026	
1027	        free(buffer); //single owner: the buffer pointer is always valid and freeable
1028	    }
1029	
1030	    // --- grow + cloning path: reopen an existing archive in a tight buffer and add an
1031	    //     entry so the rewrite must exceed the original length, forcing the grow loop. ---
1032	    {
